-- 5. okt. 2026: nemlig-produkter uden rigtig stregkode får et Open Food Facts-billede, hvor et sikkert match findes.
-- Match: samme maerke, navnelighed >= 0,6 og ingrediensliste >= 0,8 mod et Bilka/OFF-produkt med stregkode (141 raekker, gennemset af Jan).
-- Kun image_url saettes (aldrig canonical_ean/ean eller allergen-data). Kildeangivelsen vises af imageAttribution() i helpers.js.
-- Tilbagerulning: update public.products set image_url = null where id in (select product_id from public.nemlig_off_image_match_20261005);
create table public.nemlig_off_image_match_20261005 (
  product_id uuid primary key,
  matched_ean text not null,
  image_url text not null
);
alter table public.nemlig_off_image_match_20261005 enable row level security;


update public.products p set image_url = m.image_url
  from public.nemlig_off_image_match_20261005 m
 where p.id = m.product_id and p.source = 'nemlig' and p.image_url is null;
